B=http://127.0.0.1:40981/api/v1/releases/2.08; for p in "sunids/51734/annotations" "sunids/51734/homology" "sunids/51904/homology" "sunids/52467/homology" "sunids/51734/children?limit=10" "sunids/51904/children?limit=10" "sunids/51970/children?limit=10" "sunids/52467/children?limit=20"; do echo "=== $p"; curl -s -w "\nHTTP %{http_code}\n" "$B/$p" | python3 -I -c "
import sys
t=sys.stdin.read()
body,_,code=t.rpartition('HTTP ')
print('HTTP',code.strip())
try:
    import json;d=json.loads(body)
    if 'children' in d:
        for c in d['children']: print(c.get('sccs'),c.get('sunid'),c['level']['code'],c.get('description'))
        print('has_more',d.get('has_more'))
    else: print(json.dumps(d,indent=1)[:1500])
